<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, legacyUrl, prepareLegacy } from '../app'
import { featureGroups, featureRoute } from '../features'
const query=ref('')
const groups=computed(()=>featureGroups.map(g=>({...g,items:g.items.filter(f=>(f.name+' '+f.detail).includes(query.value.trim()))})).filter(g=>g.items.length))
</script>
<template><header class="feature-heading"><h1>全部功能</h1><input v-model="query" aria-label="查找功能" placeholder="查找功能" /></header><p class="muted">保留完整业务流程；尚未迁入新版的功能会打开原有页面。</p><section v-for="group in groups" :key="group.name" class="feature-group"><h2>{{group.name}}</h2><div class="feature-list"><template v-for="item in group.items" :key="item.route"><a v-if="!item.project || app.project" :href="legacyUrl(featureRoute(item,app.project))" @click="prepareLegacy(item.project ? app.project : '*')"><strong>{{item.name}}</strong><span>{{item.detail}}</span><span class="arrow" aria-hidden="true">↗</span></a><div v-else class="unavailable"><strong>{{item.name}}</strong><span>选择项目后可进入</span></div></template></div></section><p v-if="!groups.length" class="empty">没有匹配的功能。</p></template>
<style scoped>.feature-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.feature-heading h1{margin:0}.feature-heading input{padding:9px 12px;border:1px solid var(--line);border-radius:6px;background:var(--panel);max-width:220px;width:100%}.feature-group{margin:30px 0}.feature-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-top:1px solid var(--line);column-gap:32px}.feature-list a,.unavailable{display:flex;flex-direction:column;gap:5px;padding:18px 30px 18px 0;border-bottom:1px solid var(--line);position:relative;text-decoration:none;color:var(--fg)}.feature-list a:hover strong{color:var(--accent)}.feature-list span{color:var(--sub);font-size:13px}.feature-list .arrow{position:absolute;right:8px;top:20px}.unavailable{color:var(--sub)}@media(max-width:760px){.feature-list{grid-template-columns:1fr}.feature-heading{align-items:start;flex-direction:column}}</style>
